export const ScriptInputModeSchema = z
    .any()
    .superRefine((x, ctx) => {
        const schemas = [
            z.literal("file").describe("A `.vpy` file on disk, used as written."),
            z.literal("text").describe("Script text stored in the project document."),
        ];
        const { errors, failed } = schemas.reduce<{
            errors: z.core.$ZodIssue[];
            failed: number;
        }>(
            ({ errors, failed }, schema) =>
                ((result) =>
                    result.error
                        ? {
                              errors: [...errors, ...result.error.issues],
                              failed: failed + 1,
                          }
                        : { errors, failed })(schema.safeParse(x)),
            { errors: [], failed: 0 },
        );
        const passed = schemas.length - failed;
        if (passed !== 1) {
            ctx.addIssue(
                errors.length
                    ? {
                          path: [],
                          code: "invalid_union",
                          errors: [errors],
                          message: "Invalid input: Should pass single schema. Passed " + passed,
                      }
                    : {
                          path: [],
                          code: "custom",
                          errors: [errors],
                          message: "Invalid input: Should pass single schema. Passed " + passed,
                      },
            );
        }
    })
    .describe("How a `vapour_synth_script` input supplies its script.");
export type ScriptInputMode = z.infer<typeof ScriptInputModeSchema>;

/** Generated from `schema/encoder/encoder-definition.schema.json`. */
export const TextFormatSchema = z
    .any()
    .superRefine((x, ctx) => {
        const schemas = [
            z.literal("Email").describe("An email address."),
            z.literal("Url").describe("An absolute or relative URL."),
            z.literal("DateTime").describe("An ISO-8601 date or date-time."),
        ];
        const { errors, failed } = schemas.reduce<{
            errors: z.core.$ZodIssue[];
            failed: number;
        }>(
            ({ errors, failed }, schema) =>
                ((result) =>
                    result.error
                        ? {
                              errors: [...errors, ...result.error.issues],
                              failed: failed + 1,
                          }
                        : { errors, failed })(schema.safeParse(x)),
            { errors: [], failed: 0 },
        );
        const passed = schemas.length - failed;
        if (passed !== 1) {
            ctx.addIssue(
                errors.length
                    ? {
                          path: [],
                          code: "invalid_union",
                          errors: [errors],
                          message: "Invalid input: Should pass single schema. Passed " + passed,
                      }
                    : {
                          path: [],
                          code: "custom",
                          errors: [errors],
                          message: "Invalid input: Should pass single schema. Passed " + passed,
                      },
            );
        }
    })
    .describe(
        "The well-known shape of a text value, when the encoder states one.\n\nA format is evidence from the help text, not a guess: the editor validates the value and\nthe service still stores exactly what the encoder accepts.",
    );
export type TextFormat = z.infer<typeof TextFormatSchema>;

/** Generated from `schema/encoder/encoder-definition.schema.json`. */
export const TextSpecSchema = z
    .object({
        format: z
            .union([z.lazy(() => TextFormatSchema), z.null()])
            .describe("A well-known value shape the editor validates, when the encoder states one.")
            .optional(),
        max_len: z
            .union([
                z.number().int().gte(0).describe("Maximum character count."),
                z.null().describe("Maximum character count."),
            ])
            .describe("Maximum character count.")
            .optional(),
        multiline: z.boolean().describe("Whether the editor should offer a multi-line field."),
        pattern: z
            .union([
                z.string().describe("Regular expression the whole value must match."),
                z.null().describe("Regular expression the whole value must match."),
            ])
            .describe("Regular expression the whole value must match.")
            .optional(),
    })
    .strict()
    .describe("Constraints on a text parameter.");
export type TextSpec = z.infer<typeof TextSpecSchema>;

/** Generated from `schema/script/script-plugin-report.json`. */
export const VapourSynthPluginProblemSchema = z
    .object({
        context: z
            .string()
            .describe("The script section that made the call, for example `Encoding`."),
        detail: z.string().describe("One sentence naming the section and what is missing."),
        function: z
            .union([
                z
                    .string()
                    .describe(
                        "The function inside an installed namespace, when only that function is missing.",
                    ),
                z
                    .null()
                    .describe(
                        "The function inside an installed namespace, when only that function is missing.",
                    ),
            ])
            .describe(
                "The function inside an installed namespace, when only that function is missing.",
            )
            .optional(),
        namespace: z.string().describe("The plugin namespace, for example `hqdn3d`."),
        remediation: z.string().describe("What to install or remove to make the reference valid."),
    })
    .strict()
    .describe(
        "One VapourSynth plugin reference a run would use but the loaded core does not provide.\n\nThe namespace and the script section stay separate so the Video page can render the\nplugin name beside the input that calls it, instead of asking the user to read it out of\na sentence.",
    );
export type VapourSynthPluginProblem = z.infer<typeof VapourSynthPluginProblemSchema>;
